//! Actual raw-page lifecycle DATA. Only its private host can certify two CODE EOFs.
use crate::{lifecycle_policy::{self as policy,FileFacts,Patterns},state_schema_data::{self as schema,Schema},captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},reactive_raw_policy_pages::RawPolicyPages,lint::Site};
use std::{sync::Arc,io};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub struct LifecycleData{sites:Vec<Site>,notes:Vec<String>}
impl LifecycleData{pub fn sites(&self)->&[Site]{&self.sites}pub fn notes(&self)->&[String]{&self.notes}pub fn metadata(&self)->&'static crate::lint::Meta{&policy::META}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.notes.capacity().checked_mul(std::mem::size_of::<String>())?)?;for site in &self.sites{for word in [&site.rule,&site.rel,&site.msg,&site.key,&site.ident]{n=n.checked_add(word.capacity())?;}}for note in &self.notes{n=n.checked_add(note.capacity())?;}Some(n)}pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(2)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.notes)?;rows.end()}}
pub fn collect_from_pages(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<LifecycleData,Failure>{collect_using(pages,root,poll,None)}
pub fn collect_from_pages_with_patterns(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<LifecycleData,Failure>{collect_using(pages,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,native_patterns:Option<&dyn crate::native_pattern::Provider>)->Result<LifecycleData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=PatternOperation{budget:keep,poll,patterns:native_patterns};let mut schema=Schema::default();let all=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;views.code()?;let file=views.source_file()?;let mut temporary=PatternOperation{budget:local,poll,patterns:native_patterns};schema::parse_file_using(relative,file.code(),&mut schema.decls,&mut schema.latent,&mut work,&mut temporary)?;Ok(true)})();finish(pending,local,poll)})?;if !all{return Err("lifecycle schema source stopped before actual CODE EOF".into())}
 kc::reserve(&mut work,||Some(4096))?;let fixture=native_patterns.map(|provider|crate::raw_fixture_policy::Fixture::native_patterns(keep,poll,provider));let native=if let Some(actual)=fixture.as_ref(){let patterns=Patterns::with_fixture(actual);if let Some(error)=actual.take_scan_failure(){return Err(pattern_failure(error))}Some(patterns.map_err(Failure::Unsupported)?)}else{None};let patterns=if native_patterns.is_none(){Some(Patterns::new())}else{None};let mut files=Vec::new();let selected=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;views.code()?;let file=views.source_file()?;let mut temporary=PatternOperation{budget:local,poll,patterns:native_patterns};let bodies=if let Some(provider)=native_patterns{let scratch=Budget::scoped_temporaries(root).map_err(|message|oom(root,message))?;let actual=crate::raw_fixture_policy::Fixture::scanned(&scratch,poll,provider,file).map_err(pattern_failure)?;let program=Patterns::with_fixture(&actual);if let Some(error)=actual.take_scan_failure(){return Err(pattern_failure(error))}let program=program.map_err(Failure::Unsupported)?;let pending=policy::scan_using(file.code(),&program,&mut work,&mut temporary);if let Some(error)=actual.take_scan_failure(){return Err(pattern_failure(error))}pending?}else{policy::scan_using(file.code(),patterns.as_ref().expect("actual compatibility lifecycle patterns"),&mut work,&mut temporary)?};policy::row(&mut work,&mut files)?;files.push(FileFacts{relative:kc::own(&mut work,relative)?,bodies});Ok(true)})();finish(pending,local,poll)})?;if !selected{return Err("lifecycle selected source stopped before actual CODE EOF".into())}
 let output=if let Some(patterns)=native.as_ref(){assemble(&schema,&files,patterns,&mut work)}else{assemble(&schema,&files,patterns.as_ref().expect("actual compatibility lifecycle metadata"),&mut work)};if let Some(actual)=fixture.as_ref().and_then(|actual|actual.take_scan_failure()){return Err(pattern_failure(actual))}let output=output?;checked(keep,poll)?;Ok(output)})();let pending=finish(pending,keep,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"lifecycle returned capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)}

fn assemble<P:crate::raw_fixture_policy::PatternApi>(schema:&Schema,files:&[FileFacts],patterns:&Patterns<P>,work:&mut PatternOperation<'_>)->Result<LifecycleData,Failure>{let output=std::cell::RefCell::new(LifecycleData{sites:Vec::new(),notes:Vec::new()});policy::judge_using(schema,files,patterns,work,&mut|rule,relative,line,message,c|{let mut out=output.borrow_mut();policy::row(c,&mut out.sites)?;out.sites.push(Site{rule:kc::own(c,rule)?,rel:kc::own(c,relative)?,line,msg:message,key:String::new(),ident:String::new()});Ok(())},&mut|message,c|{let mut out=output.borrow_mut();policy::row(c,&mut out.notes)?;out.notes.push(message);Ok(())})?;Ok(output.into_inner())}
fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(actual)=>Failure::Operational(actual),crate::derived_selftest_policy::Failure::Assertion(message)=>Failure::Unsupported(message)}}
